import { ref } from 'vue';
export default {
  setup(props, {
    emit
  }) {
    const username = ref('');
    const email = ref('');
    const password = ref('');
    const confirmPassword = ref('');
    const submitForm = () => {
      if (password.value !== confirmPassword.value) {
        console.error('Passwords do not match');
        return;
      }
      emit('register', {
        username: username.value,
        email: email.value,
        password: password.value
      });
    };
    return {
      username,
      email,
      password,
      confirmPassword,
      submitForm
    };
  }
};
